func (c *current) onCreateTableStmt2(ine, name, cols, orderBy any) (any, error) {

	stmt := &ast.CreateTableStmt{
		Kind:        "CreateTableStmt",
		Name:        name.(*ast.Text),
		IfNotExists: ine != nil,
		Loc:         loc(c),
	}
	if cols != nil {
		stmt.Columns = cols.([]ast.ColumnDef)
	}
	if orderBy != nil {
		stmt.OrderBy = orderBy.(*ast.SQLOrderBy)
	}
	return stmt, nil

}

